/**
 * @file NetworkBridge.hh
 * @brief Parameters for NetworkBridge
 */

#ifndef __GARNET_COMPAT_PARAMS_NETWORKBRIDGE_HH__
#define __GARNET_COMPAT_PARAMS_NETWORKBRIDGE_HH__

#include "params/CreditLink.hh"

namespace gem5 {

// Bridge type enums (normally auto-generated by SLICC in gem5)
namespace enums {
enum BridgeType {
    LINK_OBJECT,  // Link -> Object (receive side)
    OBJECT_LINK   // Object -> Link (transmit side)
};
} // namespace enums

namespace ruby {

// Forward declare
namespace garnet {
class NetworkLink;
} // namespace garnet

struct NetworkBridgeParams : public CreditLinkParams {
    Cycles serdes_latency = Cycles(1);
    Cycles cdc_latency = Cycles(1);
    bool cdc_en = false;
    uint32_t link_width = 128;
    uint32_t virt_nets = 3;
    enums::BridgeType vtype = enums::LINK_OBJECT;
    garnet::NetworkLink* link = nullptr;
};

} // namespace ruby
} // namespace gem5

#endif // __GARNET_COMPAT_PARAMS_NETWORKBRIDGE_HH__
